import React, { useEffect, useState } from "react";
import api from "../services/api";

const AdminDashboard = () => {
  const [metrics, setMetrics] = useState([]);

  useEffect(() => {
    api.get("/api/agent/metrics")
      .then((response) => {
        setMetrics(response.data);
      })
      .catch((error) => {
        console.error("Error fetching metrics:", error);
      });
  }, []);

  return (
    <div className="container mx-auto p-6">
      <h2 className="text-2xl font-bold mb-4">Server Monitoring Dashboard</h2>
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {metrics.map((metric, index) => (
          <div key={index} className="bg-white shadow-md p-4 rounded-lg">
            <h3 className="text-lg font-semibold">Server: {metric.server_id}</h3>
            <p>CPU Usage: {metric.cpu_usage}%</p>
            <p>Memory Usage: {metric.memory_usage}%</p>
            <p>Disk Usage: {metric.disk_usage}%</p>
            <p>Uptime: {Math.round(metric.uptime / 3600)} hours</p>
            <p>Logs: {JSON.parse(metric.logs).slice(0, 5).join(", ")}</p>
          </div>
        ))}
      </div>
    </div>
  );
};

export default AdminDashboard;
